sources.app.tsx:
// A landscape painted from the weather now: the sky's color from where the sun
// is and how cloudy it is, the sun crossing the sky by day and the moon (in its
// real phase) and stars by night, clouds as many as the cover, and rain, snow,
// fog or lightning when Open-Meteo says so. The hills, trees and house are the
// same every time; only the weather changes.
import { kindOf, wordsFor, degrees, mix, dayIndex } from './weather'

// A small seeded random generator, so the scenery stays put between renders.
function seeded(seed: number) {
  let s = seed >>> 0 || 1
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0
    return s / 4294967296
  }
}

// Sky colors (top, horizon) by minutes from sunrise or sunset: negative is
// night, positive day.
const SKY: [number, string, string][] = [
  [-90, '#070d24', '#18264a'],
  [-40, '#141a46', '#3b3f74'],
  [-10, '#2a2c62', '#d5735b'],
  [15, '#45609f', '#f2a66f'],
  [60, '#3f7cc8', '#cfe0ea'],
  [120, '#3a7fd0', '#b7daf4'],
]

function skyAt(minutes: number): [string, string] {
  if (minutes <= SKY[0][0]) return [SKY[0][1], SKY[0][2]]
  for (let i = 1; i < SKY.length; i++) {
    if (minutes <= SKY[i][0]) {
      const t = (minutes - SKY[i - 1][0]) / (SKY[i][0] - SKY[i - 1][0])
      return [mix(SKY[i - 1][1], SKY[i][1], t), mix(SKY[i - 1][2], SKY[i][2], t)]
    }
  }
  const last = SKY[SKY.length - 1]
  return [last[1], last[2]]
}

// A ridge line across the width: a sum of sines, its phases from the seed.
// `span` keeps the hills as wide on a tall screen as on a wide one.
function ridge(span: number, base: number, amplitude: number, seed: number) {
  const random = seeded(seed)
  const waves = [0, 1, 2].map((i) => ({
    length: span * (0.9 - i * 0.28) * (0.7 + random() * 0.6),
    phase: random() * Math.PI * 2,
    height: amplitude / (i + 1),
  }))
  return (x: number) => {
    let y = base
    for (const wave of waves) y -= Math.sin((x / wave.length) * Math.PI * 2 + wave.phase) * wave.height
    return y
  }
}

function ridgePath(W: number, H: number, at: (x: number) => number) {
  const step = W / 48
  let d = `M0 ${H} L0 ${at(0).toFixed(1)}`
  for (let x = step; x <= W + 0.5; x += step) d += ` L${x.toFixed(1)} ${at(x).toFixed(1)}`
  return d + ` L${W} ${H} Z`
}

// A cloud: a flat, shaded base under a few soft, lit heaps.
function cloudParts(x: number, y: number, size: number, random: () => number) {
  const heaps = []
  const count = 3 + Math.floor(random() * 3)
  for (let i = 0; i < count; i++) {
    const t = (i + 0.5) / count
    const lift = Math.sin(t * Math.PI)
    heaps.push({
      cx: x + (t - 0.5) * size * 2.4 + (random() - 0.5) * size * 0.3,
      cy: y - size * (0.2 + lift * 0.35),
      rx: size * (0.45 + lift * 0.45) * (0.85 + random() * 0.3),
      ry: size * (0.3 + lift * 0.3) * (0.85 + random() * 0.3),
    })
  }
  return heaps
}

// The moon lit as it is tonight: 0 new, 0.5 full.
function moonPhase(epochMs: number) {
  const days = (epochMs - 947182440000) / 86400000
  const phase = (days / 29.530588853) % 1
  return phase < 0 ? phase + 1 : phase
}

function moonPath(cx: number, cy: number, r: number, phase: number) {
  const waxing = phase < 0.5
  const inner = Math.abs(Math.cos(phase * Math.PI * 2)) * r
  const crescent = phase < 0.25 || phase > 0.75
  const outerSweep = waxing ? 1 : 0
  const innerSweep = waxing ? (crescent ? 0 : 1) : crescent ? 1 : 0
  return (
    `M${cx} ${cy - r} A${r} ${r} 0 0 ${outerSweep} ${cx} ${cy + r} ` +
    `A${inner.toFixed(2)} ${r} 0 0 ${innerSweep} ${cx} ${cy - r} Z`
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const u = Math.min(W, H) / 100
  const weather = app.config.weather || {}
  if (!weather.current || !weather.daily) {
    throw new Error(weather.error || 'No weather yet')
  }
  const now = Date.now()
  const current = weather.current
  const kind = kindOf(current.code)
  const cloud = Math.max(0, Math.min(100, current.cloud ?? 50)) / 100
  const today = Math.max(0, Math.min(weather.daily.sunrise.length - 1, dayIndex(weather.daily, now)))
  const sunrise = weather.daily.sunrise[today]
  const sunset = weather.daily.sunset[today]
  const nextSunrise = weather.daily.sunrise[today + 1] ?? sunrise + 86400000

  // Minutes from the nearest sunrise or sunset, signed: + by day, - by night.
  const isDay = now >= sunrise && now <= sunset
  const minutes = isDay
    ? Math.min(now - sunrise, sunset - now) / 60000
    : -Math.min(Math.abs(now - sunset), Math.abs(now < sunrise ? sunrise - now : nextSunrise - now)) / 60000
  const night = minutes < -30
  let [skyTop, skyLow] = skyAt(minutes)
  // Clouds grey the sky; rain and storms darken it.
  const gloom = kind === 'storm' ? 0.95 : kind === 'rain' || kind === 'snow' ? 0.85 : cloud * 0.8
  const greyTop = night ? '#14171f' : kind === 'storm' ? '#3c4250' : '#7c8794'
  const greyLow = night ? '#272b36' : kind === 'storm' ? '#5b6170' : '#c4cad1'
  skyTop = mix(skyTop, greyTop, gloom)
  skyLow = mix(skyLow, greyLow, gloom * 0.9)

  const horizon = H * 0.6
  const lakeTop = H * 0.7
  const random = seeded(7)

  // The sun on its arc from sunrise to sunset; the moon on its own by night.
  const arcLeft = W * 0.08
  const arcRight = W * 0.92
  const arcHeight = H * 0.46
  let bodyX = W * 0.5
  let bodyY = horizon
  const bodyR = u * 6
  if (isDay) {
    const t = (now - sunrise) / (sunset - sunrise)
    bodyX = arcLeft + (arcRight - arcLeft) * t
    bodyY = horizon - Math.sin(t * Math.PI) * arcHeight + bodyR * 0.6
  } else {
    const start = now > sunset ? sunset : sunset - 86400000
    const end = now > sunset ? nextSunrise : sunrise
    const t = Math.max(0, Math.min(1, (now - start) / (end - start)))
    bodyX = arcLeft + (arcRight - arcLeft) * t
    bodyY = horizon - Math.sin(t * Math.PI) * arcHeight * 0.85 + bodyR * 0.6
  }
  const bodyShows = cloud < 0.92 && kind !== 'rain' && kind !== 'storm' && kind !== 'snow' && kind !== 'fog'
  const bodyDim = 1 - Math.max(0, cloud - 0.5) * 1.6

  // The land: five ridges, the far ones fading into the haze of the sky.
  const daylight = Math.max(0, Math.min(1, (minutes + 30) / 90))
  const dusk = Math.max(0, 1 - Math.abs(minutes - 5) / 50)
  let ink = mix('#070b18', '#1d3527', daylight)
  ink = mix(ink, '#231c33', dusk * 0.5)
  if (kind === 'snow') ink = mix(ink, mix('#3a4456', '#7d8c9c', daylight), 0.9)
  ink = mix(ink, night ? '#0b0d12' : '#2b3036', gloom * 0.3)
  const haze = mix(skyLow, skyTop, 0.15)
  // Fog swallows all but the nearest ridges.
  const fade = kind === 'fog' ? 2.6 : 1.15
  const land = [0, 1, 2, 3, 4].map((i) => mix(haze, ink, (kind === 'fog' ? 0.08 : 0.22) + 0.78 * Math.pow(i / 4, fade)))
  // Snow lies on the far ridges in snowy weather, and lights them a little.
  if (kind === 'snow') {
    for (let i = 0; i < 3; i++) land[i] = mix(land[i], '#f2f5f8', (0.55 - i * 0.12) * (0.4 + daylight * 0.6))
  }

  const hillSpan = Math.max(W, H * 1.6)
  const farthest = ridge(hillSpan, horizon - H * 0.12, H * 0.09, 3)
  const far = ridge(hillSpan, horizon - H * 0.04, H * 0.07, 11)
  const mid = ridge(hillSpan, horizon + H * 0.04, H * 0.04, 23)
  const near = ridge(hillSpan, H * 0.8, H * 0.03, 41)
  const front = ridge(hillSpan, H * 0.93, H * 0.025, 57)

  // Clouds, as many as the cover, drifting a little with the hours; a deck
  // of grey layers across the sky when it is overcast.
  const clouds = []
  // A big panel on an ESP32 has the least memory to spare: fewer clouds there.
  const cloudCap = app.frame.embedded && W * H > 1000000 ? 6 : 10
  const cloudCount = kind === 'fog' ? 0 : Math.round((Math.min(cloud, 0.8) / 0.8) * cloudCap)
  const drift = ((now / 3600000) * W * 0.03) % W
  const cloudLight = night ? '#373e52' : kind === 'storm' ? '#6b7180' : mix('#fbfcfd', '#cfd4da', gloom)
  const cloudShade = night ? '#22283a' : kind === 'storm' ? '#40465a' : mix(mix('#c9d1db', skyLow, 0.3), '#8e98a4', gloom)
  const cloudEdge = night ? '#4a5268' : kind === 'storm' ? '#80869a' : mix('#ffffff', '#e1e5ea', gloom)
  for (let i = 0; i < cloudCount; i++) {
    const depth = i / Math.max(1, cloudCount - 1)
    const size = u * (5 + random() * 5) * (0.6 + depth * 0.7)
    const x = ((random() * W * 1.3 + drift * (0.5 + depth)) % (W * 1.3)) - W * 0.15
    const y = H * (0.1 + random() * 0.3) + depth * H * 0.06
    const heaps = cloudParts(x, y, size, random)
    // Far clouds take on the sky's color. (Colors, not a group's opacity: a
    // group with opacity costs a layer the size of the cloud.)
    const away = (1 - depth) * 0.25
    const shade = mix(cloudShade, skyTop, away)
    const light = mix(cloudLight, skyTop, away)
    const edge = mix(cloudEdge, skyTop, away)
    clouds.push(
      <g>
        <ellipse cx={x} cy={y} rx={size * 1.7} ry={size * 0.3} fill={shade} />
        {heaps.map((p) => <ellipse cx={p.cx} cy={p.cy + p.ry * 0.25} rx={p.rx} ry={p.ry} fill={shade} />)}
        {heaps.map((p) => <ellipse cx={p.cx - p.rx * 0.06} cy={p.cy - p.ry * 0.06} rx={p.rx * 0.9} ry={p.ry * 0.85} fill={light} />)}
        {heaps.map((p) => <ellipse cx={p.cx - p.rx * 0.2} cy={p.cy - p.ry * 0.35} rx={p.rx * 0.45} ry={p.ry * 0.35} fill={edge} opacity={0.7} />)}
      </g>,
    )
  }
  const deck = []
  if (cloud > 0.6) {
    const deckRandom = seeded(31)
    const strength = (cloud - 0.6) / 0.4
    for (let i = 0; i < 14; i++) {
      const y = H * (0.02 + deckRandom() * 0.42)
      const rx = W * (0.25 + deckRandom() * 0.35)
      const tone = mix(cloudShade, cloudLight, deckRandom())
      deck.push(
        <ellipse cx={deckRandom() * W * 1.2 - W * 0.1} cy={y} rx={rx} ry={H * (0.025 + deckRandom() * 0.04)} fill={tone} opacity={0.35 * strength} />,
      )
    }
  }

  // Stars where the night is clear enough.
  const stars = []
  if (night && cloud < 0.75) {
    const starRandom = seeded(99)
    for (let i = 0; i < 90; i++) {
      const x = starRandom() * W
      const y = starRandom() * horizon * 0.85
      const r = (0.4 + starRandom() * starRandom() * 1.6) * u * 0.3
      stars.push(<circle cx={x} cy={y} r={r} fill="#f4f1e0" opacity={(0.35 + starRandom() * 0.65) * (1 - cloud / 0.75)} />)
    }
  }

  // Rain, snow, fog and lightning.
  const weatherMarks = []
  const windLean = Math.max(-1, Math.min(1, ((current.wind ?? 10) / 40) * (Math.sin(((current.windDirection ?? 270) * Math.PI) / 180) > 0 ? -1 : 1)))
  if (kind === 'rain' || kind === 'drizzle' || kind === 'storm') {
    const rainRandom = seeded(5)
    const count = kind === 'drizzle' ? 90 : current.code === 65 || current.code === 82 || kind === 'storm' ? 260 : 170
    const length = (kind === 'drizzle' ? 2.2 : 4) * u
    for (let i = 0; i < count; i++) {
      const x = rainRandom() * (W + H * 0.3) - H * 0.15
      const y = rainRandom() * H * 0.95
      weatherMarks.push(
        <line x1={x} y1={y} x2={x + windLean * length * 0.5} y2={y + length} stroke="#d8e2ee" strokeWidth={u * 0.22} strokeLinecap="round" opacity={0.25 + rainRandom() * 0.35} />,
      )
    }
  }
  if (kind === 'snow') {
    const snowRandom = seeded(6)
    const count = current.code === 75 || current.code === 86 ? 260 : 160
    for (let i = 0; i < count; i++) {
      const r = (0.25 + snowRandom() * 0.55) * u
      weatherMarks.push(<circle cx={snowRandom() * W} cy={snowRandom() * H} r={r} fill="#ffffff" opacity={0.55 + snowRandom() * 0.45} />)
    }
  }
  if (kind === 'fog') {
    const fogRandom = seeded(13)
    for (let i = 0; i < 16; i++) {
      const y = horizon - H * 0.16 + fogRandom() * H * 0.45
      weatherMarks.push(
        <ellipse cx={fogRandom() * W} cy={y} rx={W * (0.3 + fogRandom() * 0.4)} ry={H * (0.03 + fogRandom() * 0.04)} fill={night ? '#5a6273' : '#eef0f2'} opacity={0.22} />,
      )
    }
  }
  let flash = null
  if (kind === 'storm') {
    const x = W * 0.63
    const y = H * 0.18
    const s = u * 1.6
    flash = (
      <g>
        <rect width={W} height={H} fill="#f5f0ff" opacity={0.08} />
        <polygon
          points={[
            [x, y], [x - 4 * s, y + 9 * s], [x - 1 * s, y + 9 * s], [x - 5 * s, y + 19 * s],
            [x + 3 * s, y + 7 * s], [x, y + 7 * s], [x + 3 * s, y],
          ].map((p) => p.join(',')).join(' ')}
          fill="#fff5c4"
        />
      </g>
    )
  }

  // Trees and the house sit on the near ridge.
  const trees = []
  const treeColor = mix(land[3], land[4], 0.55)
  const treeRandom = seeded(77)
  for (let i = 0; i < 26; i++) {
    const x = treeRandom() * W
    if (x > W * 0.66 && x < W * 0.8) continue
    const h = u * (4 + treeRandom() * 6)
    const y = near(x) + u * 0.8
    const w = h * 0.42
    trees.push(<polygon points={`${x},${y - h} ${x - w},${y} ${x + w},${y}`} fill={treeColor} />)
    trees.push(<polygon points={`${x},${y - h * 1.25} ${x - w * 0.7},${y - h * 0.45} ${x + w * 0.7},${y - h * 0.45}`} fill={treeColor} />)
  }
  const houseX = W * 0.72
  const houseY = near(houseX) + u * 0.5
  const hw = u * 7
  const hh = u * 4.5
  const lit = !isDay || minutes < 40 || gloom > 0.7
  const house = (
    <g>
      <rect x={houseX - hw / 2} y={houseY - hh} width={hw} height={hh + u} fill={land[4]} />
      <polygon points={`${houseX - hw * 0.62},${houseY - hh} ${houseX},${houseY - hh - u * 3.6} ${houseX + hw * 0.62},${houseY - hh}`} fill={land[4]} />
      <rect x={houseX + hw * 0.18} y={houseY - hh - u * 3.4} width={u * 1.1} height={u * 2.4} fill={land[4]} />
      <rect x={houseX - hw * 0.32} y={houseY - hh * 0.72} width={u * 1.5} height={u * 1.5} fill={lit ? '#ffcf73' : land[2]} />
      <rect x={houseX + hw * 0.1} y={houseY - hh * 0.72} width={u * 1.5} height={u * 1.5} fill={lit ? '#ffcf73' : land[2]} />
    </g>
  )

  // The lake mirrors the sky, darker, with the sun or moon as a glimmer.
  const lakeTopColor = mix(skyLow, land[2], 0.5)
  const lakeLowColor = mix(skyTop, land[3], 0.55)
  const glimmers = []
  if (bodyShows) {
    for (let i = 0; i < 7; i++) {
      const y = lakeTop + u * 1.2 + i * u * 1.3
      const w = u * (8 - i * 0.7) * (isDay ? 1 : 0.7)
      glimmers.push(<rect x={bodyX - w / 2} y={y} width={w} height={u * 0.35} rx={u * 0.17} fill={isDay ? '#fff3d1' : '#e9edf5'} opacity={(0.55 - i * 0.06) * bodyDim} />)
    }
  }

  const temperature = degrees(current.temperature)
  const words = wordsFor(current.code)
  const high = weather.daily.high[today]
  const low = weather.daily.low[today]
  const textColor = '#ffffff'
  const big = Math.min(H * 0.24, W * 0.2)
  const left = u * 5
  const bottom = H - u * 5

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <linearGradient id="sky" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2={horizon}>
        <stop offset="0" stopColor={skyTop} />
        <stop offset="1" stopColor={skyLow} />
      </linearGradient>
      <radialGradient id="glow" gradientUnits="userSpaceOnUse" cx={bodyX} cy={bodyY} r={u * (isDay ? 38 : 22)}>
        <stop offset="0" stopColor={isDay ? '#fff1c9' : '#dfe6ff'} stopOpacity={(isDay ? 0.7 : 0.25) * bodyDim} />
        <stop offset="1" stopColor={isDay ? '#fff1c9' : '#dfe6ff'} stopOpacity="0" />
      </radialGradient>
      <linearGradient id="lake" gradientUnits="userSpaceOnUse" x1="0" y1={lakeTop} x2="0" y2={H}>
        <stop offset="0" stopColor={lakeTopColor} />
        <stop offset="1" stopColor={lakeLowColor} />
      </linearGradient>
      <linearGradient id="shade" gradientUnits="userSpaceOnUse" x1="0" y1={H * 0.55} x2="0" y2={H}>
        <stop offset="0" stopColor="#000000" stopOpacity="0" />
        <stop offset="1" stopColor="#000000" stopOpacity="0.35" />
      </linearGradient>

      <rect width={W} height={H} fill="url(#sky)" />
      {stars}
      {bodyShows ? <rect width={W} height={H} fill="url(#glow)" /> : null}
      {bodyShows && isDay ? <circle cx={bodyX} cy={bodyY} r={bodyR} fill="#fff4d6" opacity={bodyDim} /> : null}
      {bodyShows && !isDay ? (
        <g>
          <circle cx={bodyX} cy={bodyY} r={bodyR * 0.8} fill={mix(skyTop, '#ffffff', 0.12)} opacity={bodyDim} />
          <path d={moonPath(bodyX, bodyY, bodyR * 0.8, moonPhase(now))} fill="#f1efe3" opacity={bodyDim} />
        </g>
      ) : null}
      {deck}
      {clouds.slice(0, Math.ceil(cloudCount / 2))}
      <path d={ridgePath(W, H, farthest)} fill={land[0]} />
      {clouds.slice(Math.ceil(cloudCount / 2))}
      <path d={ridgePath(W, H, far)} fill={land[1]} />
      <path d={ridgePath(W, H, mid)} fill={land[2]} />
      <rect x={0} y={lakeTop} width={W} height={H - lakeTop} fill="url(#lake)" />
      {glimmers}
      <path d={ridgePath(W, H, near)} fill={land[3]} />
      {trees}
      {house}
      <path d={ridgePath(W, H, front)} fill={land[4]} />
      {weatherMarks}
      {flash}
      <rect x={0} y={H * 0.55} width={W} height={H * 0.45} fill="url(#shade)" />

      <text x={left} y={bottom - u * 6.5 - big * 0.74 - u * 2.5} fontFamily="FiraGO" fontSize={u * 3.2} fill={textColor} opacity={0.9}>
        {(weather.place || '').toUpperCase()}
      </text>
      <text x={left - big * 0.04} y={bottom - u * 6.5} fontFamily="FiraGO" fontWeight={300} fontSize={big} fill={textColor}>
        {temperature}
      </text>
      <text x={left} y={bottom} fontFamily="FiraGO" fontSize={u * 4.2} fill={textColor}>
        {`${words} · feels like ${degrees(current.feelsLike)}`}
      </text>
      <text x={W - u * 5} y={bottom} fontFamily="FiraGO" fontSize={u * 4.2} fill={textColor} textAnchor="end" opacity={0.9}>
        {`${degrees(high)} / ${degrees(low)}`}
      </text>
    </svg>
  )
}

